"no-store\",\n   headers:{\"Authorization\":\"Bearer \"+wormstarAccess,...(data===undefined?{}:{\"Content-Type\":\"application/json\"})},\n   ...(data===undefined?{}:{body:JSON.stringify(data)})});\n const result=await response.json().catch(()=>({error:\"Invalid API response\"}));\n if(!response.ok)throw Error(result.error||\"HTTP \"+response.status);\n return result;\n}\n$(\"#scanRun\").addEventListener(\"click\",async()=>{\n const button=$(\"#scanRun\"),output=$(\"#scanResult\");output.textContent=\"\";\n if(!$(\"#scanConsent\").checked){output.textContent=\"يجب تأكيد ملكية النطاق والتصريح.\";return;}\n button.disabled=true;output.textContent=\"جارٍ إجراء طلب تدقيق واحد...\";\n try{\n   const result=await opsRequest(\"/api/security/header-audit\",{target:$(\"#scanTarget\").value});\n   output.textContent=JSON.stringify(result,null,2);\n }catch(error){output.textContent=\"تعذر الفحص: \"+error.message}\n finally{button.disabled=false;}\n});\n$(\"#agentRun\").addEventListener(\"click\",async()=>{\n const button=$(\"#agentRun\"),output=$(\"#agentResult\"),task=$(\"#opsTask\").value.trim();\n if(!task){output.textContent=\"أدخل مهمة أولاً\";return;}\n button.disabled=true;output.textContent=\"جارٍ تنفيذ التحليل المصرح به...\";\n try{\n   const data=await opsRequest(\"/api/agents/run\",{agent:$(\"#opsAgent\").value,task});\n   output.textContent=data.answer+\"\\n\\nModel: \"+data.modelUsed+\"\\nReferences: \"+(data.sourceIds||[]).map(x=>x.title).join(\"، \");\n }catch(error){output.textContent=\"تعذر تشغيل الوكيل: \"+error.message}\n finally{button.disabled=false;}\n});\n$(\"#ragStatusBtn\").addEventListener(\"click\",async()=>{\n try{$(\"#ragOutput\").textContent=JSON.stringify(await opsRequest(\"/api/rag/status\"),null,2)}\n catch(error){$(\"#ragOutput\").textContent=String(error.message)}\n});\n$(\"#ragIndexBtn\").addEventListener(\"click\",async()=>{\n const button=$(\"#ragIndexBtn\"),output=$(\"#ragOutput\");button.disabled=true;\n let cursor=\"\",count=0,batches=0;\n try{\n   for(;batches<100;batches++){\n     const data=await opsRequest(\"/api/rag/reindex\",{cursor,limit:4});\n     count+=data.indexedDocuments||0;\n     output.textContent=\"تمت فهرسة \"+count+\" وثيقة في \"+(batches+1)+\" دفعة. آخر مؤشر: \"+(data.nextCursor||\"\");\n     if(data.done){output.textContent+=\"\\nاكتملت الفهرسة. قد تتأخر ظهور المتجهات الجديدة قليلًا.\";break;}\n     if(!data.nextCursor||data.nextCursor===cursor)throw Error(\"تعذّر متابعة المؤشر\");\n     cursor=data.nextCursor;\n   }\n }catch(error){output.textContent+=\"\\nفشلت الفهرسة: \"+error.message+\"\\nيمكن إعادة التشغيل بأمان.\"}\n finally{button.disabled=false;}\n});\n\n// Event delegation also handles the mobile drawer, which clones sidebar HTML.\ndocument.addEventListener(\"click\",(event)=>{\n  if(!event.target.closest(\"[data-open-audit]\"))return;\n  // A separate tab preserves the in-memory owner login in the Sentinel tab.\n  window.open(\"/audit/\",\"_blank\",\"noopener,noreferrer\");\n});\n$(\"#profileMore\").addEventListener(\"click\",()=>toast(lang===\"ar\"?\"ملف محلي تجريبي\":\"Local demo profile\"));\nif(\"serviceWorker\" in navigator && location.protocol.startsWith(\"http\")){window.addEventListener(\"load\",()=>navigator.serviceWorker.register(\"./sw.js\").catch(()=>{}))}\n</script>\n<script src=\"/terminal.js\" defer></script>\n</body></html>\n";
const MANIFEST = "{\n  \"name\": \"Wormstar Sentinel Workspace\",\n  \"short_name\": \"Wormstar\",\n  \"description\": \"Responsive defensive cybersecurity workspace\",\n  \"start_url\": \"./\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0a101d\",\n  \"theme_color\": \"#0a101d\",\n  \"lang\": \"ar\",\n  \"dir\": \"rtl\",\n  \"icons\": []\n}";
const SW = "const CACHE = \"wormstar-sentinel-ui-local\";\nconst CORE = [\"./\", \"./index.html\", \"./manifest.webmanifest\"];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(CORE)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys()\n      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))\n      .then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const request = event.request;\n  const url = new URL(request.url);\n  if (request.method !== \"GET\" || url.origin !== self.location.origin) return;\n  const shell = url.pathname === \"/\" || url.pathname === \"/index.html\";\n  const manifest = url.pathname === \"/manifest.webmanifest\";\n  if (!shell && !manifest) return;\n\n  // Network first: never lock iPhone users into a cached, broken JS build.\n  event.respondWith((async () => {\n    try {\n      const response = await fetch(request, { cache: \"no-store\" });\n      if (response.ok && response.type === \"basic\") {\n        const cache = await caches.open(CACHE);\n        await cache.put(request, response.clone());\n      }\n      return response;\n    } catch {\n      const cached = await caches.match(request);\n      if (cached) return cached;\n      if (shell) return (await caches.match(\"./index.html\")) || Response.error();\n      return Response.error();\n    }\n  })());\n});\n";

const TERMINAL_JS = "/* The terminal uses a separate, private host and a separate in-memory token. */\n(() => {\n  'use strict';\n  const el = id => document.getElementById(id);\n  if (!el('wsTermConnect')) return;\n  let origin = '', token = '', socket = null, pending = null, history = [], lastGoal = '', busy = false, generation = 0;\n  const status = text => { el('wsTermStatus').textContent = text; };\n  const connected = () => Boolean(token && socket && socket.readyState === WebSocket.OPEN);\n  function controls() {\n    const up = connected();\n    el('wsTermInput').disabled = !up;\n    el('wsTermSend').disabled = !up;\n    el('wsTermGoal').disabled = busy;\n    el('wsTermDisconnect').disabled = !token;\n    el('wsTermPlan').disabled = !up || busy || !el('wsTermPlan').dataset.allowed;\n    el('wsTermApprove').disabled = !up || busy || !pending || !el('wsTermApprove').dataset.allowed;\n  }\n  function append(text) {\n    // Plain text prevents command output from becoming executable markup.\n    const cleaned = String(text).replace(/\\x1b\\[[0-?]*[ -/]*[@-~]/g, '').replace(/\\r/g, '');\n    const out = el('wsTermOutput');\n    out.textContent = (out.textContent + cleaned).slice(-120000);\n    out.scrollTop = out.scrollHeight;\n  }\n  function disconnect() {\n    const previous = socket;\n    socket = null; token = ''; origin = ''; pending = null; history = []; busy = false; generation++;\n    delete el('wsTermPlan').dataset.allowed;\n    delete el('wsTermApprove').dataset.allowed;\n    if (previous) previous.close();\n    controls();\n  }\n  function validateOrigin(value) {\n    const url = new URL(value);\n    const local = ['localhost', '127.0.0.1'].includes(url.hostname);\n    if (url.protocol !== 'https:' && !(local && url.protocol === 'http:')) throw Error('استخدم HTTPS خاصًا أو localhost على نفس الجهاز.');\n    if (url.username || url.password || url.pathname !== '/' || url.search || url.hash) throw Error('أدخل عنوان الخادم فقط دون مسار أو بيانات دخول.');\n    return url.origin;\n  }\n  async function api(path, body) {\n    if (!origin || !token) throw Error('الطرفية غير متصلة.');\n    const response = await fetch(origin + path, {method:body === undefined ? 'GET' : 'POST', cache:'no-store',\n      headers:{Authorization:'Bearer ' + token, ...(body === undefined ? {} : {'Content-Type':'application/json'})},\n      ...(body === undefined ? {} : {body:JSON.stringify(body)})});\n    const result = await response.json().catch(() => ({}));\n    if (!response.ok) throw Error(typeof result.detail === 'string' ? result.detail : 'HTTP ' + response.status);\n    return result;\n  }\n  el('wsTermConnect').addEventListener('click', async () => {\n    el('wsTermConnect').disabled = true;\n    try {\n      disconnect();\n      origin = validateOrigin(el('wsTermEndpoint').value.trim());\n      token = el('wsTermToken').value.trim();\n      if (!/^[A-Za-z0-9_-]{24,256}$/.test(token)) throw Error('مفتاح الطرفية غير صالح.');\n      const health = await api('/api/health');\n      if (!health.container_running) throw Error('الحاوية غير متاحة أو لم تجتز التحقق الأمني.');\n      if (!Array.isArray(health.capabilities) || !health.capabilities.includes('terminal')) throw Error('صلاحية الطرفية غير مفعلة.');\n      el('wsTermPlan').dataset.allowed = health.capabilities.includes('plan') ? '1' : '';\n      el('wsTermApprove').dataset.allowed = health.capabilities.includes('execute') ? '1' : '';\n      el('wsTermToken').value = '';\n      const url = new URL(origin); url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:'; url.pathname = '/ws/terminal';\n      const active = new WebSocket(url.toString(), ['wormstar-terminal', 'auth.' + token]);\n      socket = active;\n      active.onopen = () => { if (socket !== active) return; status('متصل بالحاوية الخاصة.'); controls(); el('wsTermInput').focus(); };\n      active.onmessage = event => { if (socket === active) append(event.data); };\n      active.onerror = () => { if (socket === active) status('تعذّر اتصال WebSocket؛ تحقق من إعداد البوابة والأصل المسموح.'); };\n      active.onclose = () => { if (socket === active) { disconnect(); status('انقطع الاتصال؛ أعد إدخال مفتاح الجلسة.'); } };\n      status('جارٍ الاتصال بالحاوية...');\n    } catch (error) { disconnect(); status('فشل الاتصال: ' + String(error.message || error)); }\n    finally { el('wsTermConnect').disabled = false; }\n  });\n  el('wsTermDisconnect').addEventListener('click', () => { disconnect(); status('انقطع الاتصال.'); });\n  el('wsTermForm').addEventListener('submit', event => {\n    event.preventDefault();\n    const command = el('wsTermInput').value;\n    if (!connected() || command.length > 4000) return;\n    socket.send(JSON.stringify({type:'input', data:command + '\\n'}));\n    el('wsTermInput').value = '';\n  });\n  el('wsTermGoal').addEventListener('input', () => { pending = null; controls(); });\n  el('wsTermPlan').addEventListener('click', async () => {\n    const goal = el('wsTermGoal').value.trim();\n    if (goal.length < 3) { status('اكتب المهمة أولاً.'); return; }\n    if (goal !== lastGoal) { history = []; lastGoal = goal; }\n    pending = null; busy = true; controls();\n    const current = generation;\n    try {\n      const result = await api('/api/agent/plan', {goal, history});\n      if (generation !== current || !connected()) return;\n      el('wsTermExplanation').textContent = result.explanation || '';\n      el('wsTermCommand').textContent = Array.isArray(result.argv) ? result.argv.map(x => JSON.stringify(x)).join(' ') : '';\n      if (!result.done && Array.isArray(result.argv) && typeof result.approval_id === 'string') { pending = {argv:result.argv, approval_id:result.approval_id}; status('راجع الأمر ثم وافق على تنفيذه.'); }\n      else status('النموذج يعتبر المهمة مكتملة؛ راجع النتيجة.');\n    } catch (error) { if (generation === current) status('فشل التخطيط: ' + String(error.message || error)); }\n    finally { if (generation === current) { busy = false; controls(); } }\n  });\n  el('wsTermApprove').addEventListener('click', async () => {\n    if (!pending) return;\n    const proposal = pending; pending = null; busy = true; controls();\n    const current = generation;\n    try {\n      const result = await api('/api/agent/execute', {argv:proposal.argv, approval_id:proposal.approval_id, approved:true});\n      if (generation !== current || !connected()) return;\n      const output = 'exit_code=' + result.exit_code + '\\n' + result.output + (result.truncated ? '\\n[truncated]' : '');\n      el('wsTermResult').textContent = output;\n      history.push({argv:proposal.argv, result:output.slice(0,4000)}); history = history.slice(-8);\n      status('اكتمل الأمر؛ راجع النتيجة قبل الخطوة التالية.');\n    } catch (error) { if (generation === current) status('فشل التنفيذ: ' + String(error.message || error)); }\n    finally { if (generation === current) { busy = false; controls(); } }\n  });\n  if (['localhost','127.0.0.1'].includes(location.hostname)) el('wsTermEndpoint').value = location.origin;\n  controls();\n})();\n";

function terminalConnectOrigins(value) {
  if (typeof value !== "string" || value.length > 2048) return "";
  try {
    const url = new URL(value);
    const local = ["localhost", "127.0.0.1"].includes(url.hostname);
    if ((url.protocol !== "https:" && !(local && url.protocol === "http:")) ||
        url.username || url.password || url.pathname !== "/" || url.search || url.hash) return "";
    const ws = new URL(url.origin);
    ws.protocol = url.protocol === "https:" ? "wss:" : "ws:";
    return " " + url.origin + " " + ws.origin;
  } catch { return ""; }
}

function response(body, type, status = 200, terminalBackend = "") {
  return new Response(body, {
    status,
    headers: {
      "Content-Type": type,
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
      "Content-Security-Policy": "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; img-src 'self' data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; script-src 'self' 'unsafe-inline'; connect-src 'self'" + (type.startsWith("text/html") ? terminalConnectOrigins(terminalBackend) : "")
    }
  });
}


function apiReply(value, status = 200) {
  return Response.json(value, {
    status,
    headers: {
      "Cache-Control": "no-store",
      "Referrer-Policy": "no-referrer",
      "X-Content-Type-Options": "nosniff"
    }
  });
}

// Only the existing Core's token verification decides who may chat.
// The preview Worker never stores, logs, or embeds a shared secret.
async function forwardCore(request, env, path) {
  const readonly = path === "/api/rag/status" || path === "/api/agents" || path === "/api/repo/status" || path === "/api/goclaw/status";
  if (request.method !== (readonly ? "GET" : "POST")) return apiReply({error:"Method not allowed"}, 405);
  const origin = request.headers.get("Origin");
  if (origin && origin !== new URL(request.url).origin) return apiReply({error:"Forbidden origin"}, 403);
  const auth = request.headers.get("Authorization") || "";
  const given = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  if (given.length < 8 || given.length > 512 || given.includes(String.fromCharCode(10)) || given.includes(String.fromCharCode(13))) return apiReply({error:"Wormstar owner token required"}, 401);
  if (!env.CORE || typeof env.CORE.fetch !== "function") return apiReply({error:"Wormstar Core is not connected"}, 503);

  const chat = !readonly && path !== "/api/auth";
  let boundedBody;
  if (chat) {
    if (!(request.headers.get("Content-Type") || "").toLowerCase().startsWith("application/json")) {
      return apiReply({error:"JSON required"}, 415);
    }
    const rawLength = request.headers.get("Content-Length");
    if (rawLength && (!Number.isSafeInteger(Number(rawLength)) || Number(rawLength) < 0 || Number(rawLength) > 65536)) {
      return apiReply({error:"Request too large"}, 413);
    }
    if (!request.body) return apiReply({error:"Request body required"}, 400);
    // Bound the actual bytes, not just an optional Content-Length header.
    boundedBody = new Uint8Array(await request.arrayBuffer());
    if (boundedBody.byteLength > 65536) return apiReply({error:"Request too large"}, 413);
  }

  const headers = new Headers({"Authorization":auth, "Accept":"application/json"});
  if (chat) headers.set("Content-Type","application/json");
  try {
    const forwarded = new Request("https://wormstar-core.internal" + path, {
      method:readonly?"GET":"POST",
      headers,
      ...(chat ? {body:boundedBody} : {})
    });
    const upstream = await env.CORE.fetch(forwarded);
    if (!(upstream.headers.get("Content-Type") || "").toLowerCase().includes("application/json")) {
      return apiReply({error:"Unexpected Core response"}, 502);
    }
    return new Response(upstream.body, {
      status:upstream.status,
      headers: {
        "Content-Type":"application/json; charset=utf-8",
        "Cache-Control":"no-store",
        "Referrer-Policy":"no-referrer",
        "X-Content-Type-Options":"nosniff"
      }
    });
  } catch {
    return apiReply({error:"Core connection failed"}, 502);
  }
}

// The second lab is served as a local module, not proxied across
// Cloudflare accounts. Its static analysis dashboard never uploads files.
async function auditPage(request, path) {
  const url=new URL(request.url);
  url.pathname=path.slice('/audit'.length)||'/';
  const upstream=await AUDIT_APP.fetch(new Request(url.toString(),{
    method:request.method,
    headers:{Accept:request.headers.get('Accept')||'*/*'}
  }));
  if (request.method!=='GET' || !['/','/index.html'].includes(url.pathname) || upstream.status!==200)
    return upstream;
  let html=await upstream.text();
  const sample='fetch("/api/sample"';
  if(!html.includes(sample))return new Response('Audit dashboard source mismatch',{status:503});
  html=html.replace(sample,'fetch("/audit/api/sample"');
  const banner='<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:13px 18px;margin-top:14px;border:1px solid #2f6d8b;border-radius:12px;background:#0c2434;color:#e5faff;font-size:13px"><strong>WORMSTAR UNIFIED LAB · STATIC AUDIT</strong><span><a style="margin-inline:8px" href="/">← Wormstar Sentinel</a><a style="margin-inline:8px" href="https://github.com/abdulstarzeki001-sketch/Star-Cyber-Audit-iSH" target="_blank" rel="noopener noreferrer">iSH Analyzer Source</a></span></div>';
  html=html.replace('<div class="wrapper">','<div class="wrapper">'+banner);
  const headers=new Headers(upstream.headers);
  headers.set('Cache-Control','no-store');
  headers.delete('Content-Length');
  return new Response(html,{status:200,headers});
}

export default {
  async fetch(request, env) {
    const path = new URL(request.url).pathname;
    if (["/api/auth","/api/chat","/api/rag/status","/api/rag/reindex","/api/security/header-audit","/api/agents","/api/agents/run","/api/repo/status","/api/repo/sync","/api/repo/ask","/api/goclaw/status"].includes(path)) {
      return forwardCore(request, env, path);
    }
    if (path === "/osint" || path.startsWith("/osint/")) {
      const url = new URL(request.url);
      url.pathname = path === "/osint" ? "/" : path.slice("/osint".length) || "/";
      return OSINT_APP.fetch(new Request(url.toString(), {method:request.method}));
    }
    if (path === "/audit" || path.startsWith("/audit/")) {
      return auditPage(request,path);
    }
    if (path === "/api/health" && request.method === "GET") {
      return apiReply({ok:true,service:"wormstar-sentinel-preview",coreBound:!!env.CORE});
    }
    if (request.method !== "GET" && request.method !== "HEAD") {
      return response("Method not allowed", "text/plain; charset=utf-8", 405);
    }
    if (path === "/" || path === "/index.html") {
      return response(request.method === "HEAD" ? null : INDEX, "text/html; charset=utf-8", 200, env?.TERMINAL_UI_BACKEND_ORIGIN || "");
    }
    if (path === "/terminal.js") {
      return response(request.method === "HEAD" ? null : TERMINAL_JS, "text/javascript; charset=utf-8");
    }
    if (path === "/manifest.webmanifest") {
      return response(request.method === "HEAD" ? null : MANIFEST, "application/manifest+json; charset=utf-8");
    }
    if (path === "/sw.js") {
      return response(request.method === "HEAD" ? null : SW, "text/javascript; charset=utf-8");
    }
    return response("Not found", "text/plain; charset=utf-8", 404);
  }
};
